// Walk published docs pages in left-nav order for llms.txt and family full-text files.
//
// Mirrors Docusaurus autogenerated sidebars: `_category_.json` `position` and
// page `sidebar_position`, with Web Tools / Desktop Tools children
// sorted by label (see docs/src/sidebar/sortToolsSidebar.mjs). Does not guess
// permalinks from filenames — README.md / index.md become the folder URL.
//
// Generated-index category landings have no source file and are omitted; their
// children still appear under the category heading.
//
// Dependency-free ESM. Node >= 18.

import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { basename, join, relative } from 'node:path';

import {
  categoryInfo,
  derivePageProse,
  docPathForRel,
  INDEX_BASENAMES,
  isPublishablePageName,
  normalizeForAgents,
  readJson,
  sidebarPositionOf,
  stripHtml,
} from './docsMarkdown.mjs';

const ALPHA_SORTED_DIR_NAMES = new Set(['web-tools', 'desktop-tools']);

function titleCase(slug) {
  return slug
    .split('-')
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
    .join(' ');
}

function categoryMeta(dir) {
  const cat = readJson(join(dir, '_category_.json'), {});
  return {
    label: cat.label || titleCase(basename(dir)),
    position: cat.position ?? 999,
    description: cat.link && cat.link.description ? stripHtml(cat.link.description) : '',
  };
}

/**
 * Family id for a docs-root-relative path. Keep the set under 10 files so an
 * agent can pick one ingest. Web Tools is one family; Desktop Tools
 * is three (a single ECT dump is ~570 KB). Small site sections share `overview`.
 * Unknown top-level folders keep their slug until they are assigned.
 */
const OVERVIEW_TOPS = new Set([
  'intro',
  'privacy',
  'getting-started',
  'hosted-tableau-mcp',
  'extras',
  'prompts',
  'tableau-authoring',
  'release-notes',
]);
const DEVELOPERS_TOPS = new Set(['developers', 'enterprise']);
const ECT_SHEETS = new Set(['workbook', 'worksheet', 'dashboard', 'storyboard']);
const ECT_DATA = new Set(['data-source', 'fields', 'binder', 'template']);

export function familyIdForRel(rel) {
  const segs = String(rel)
    .replace(/\\/g, '/')
    .replace(/\.(mdx|md)$/, '')
    .split('/');
  const top = segs[0];
  if (top === 'web-tools') return 'web-tools';
  if (top === 'desktop-tools') {
    const cat = segs[1];
    if (ECT_SHEETS.has(cat)) return 'desktop-tools-sheets';
    if (ECT_DATA.has(cat)) return 'desktop-tools-data';
    return 'desktop-tools-session';
  }
  if (top === 'configuration') return 'configuration';
  if (DEVELOPERS_TOPS.has(top)) return 'developers';
  if (OVERVIEW_TOPS.has(top) || segs.length === 1) return 'overview';
  return top;
}

export function familyTitle(familyId, pages) {
  switch (familyId) {
    case 'overview':
      return 'Overview';
    case 'configuration':
      return 'Configuration';
    case 'developers':
      return 'Developers and enterprise';
    case 'web-tools':
      return 'Web Tools';
    case 'desktop-tools-sheets':
      return 'Desktop Tools / Sheets';
    case 'desktop-tools-data':
      return 'Desktop Tools / Data';
    case 'desktop-tools-session':
      return 'Desktop Tools / Session, search, and API';
    default:
      return pages[0]?.category || titleCase(familyId);
  }
}

function pageRecord(pageAbs, docsRoot, env) {
  const rel = relative(docsRoot, pageAbs).replace(/\\/g, '/');
  const { title, summary } = derivePageProse(pageAbs);
  const raw = readFileSync(pageAbs, 'utf8');
  return {
    abs: pageAbs,
    rel,
    title,
    summary,
    docPath: docPathForRel(rel),
    body: normalizeForAgents(raw, env),
    category: categoryInfo(pageAbs).label,
    familyId: familyIdForRel(rel),
  };
}

function listDirEntries(dir) {
  if (!existsSync(dir)) return [];
  return readdirSync(dir, { withFileTypes: true });
}

function subtreeHasPages(node) {
  if (node.type === 'page') return true;
  return (node.children ?? []).some(subtreeHasPages);
}

function walkDir(dir, docsRoot) {
  const pages = [];
  const subdirs = [];
  let indexPage = null;
  for (const ent of listDirEntries(dir)) {
    if (ent.name.startsWith('_')) continue;
    const abs = join(dir, ent.name);
    if (ent.isDirectory()) {
      subdirs.push(ent.name);
      continue;
    }
    if (!isPublishablePageName(ent.name)) continue;
    if (INDEX_BASENAMES.has(ent.name)) indexPage = abs;
    else pages.push(abs);
  }
  pages.sort(
    (a, b) =>
      sidebarPositionOf(readFileSync(a, 'utf8')) - sidebarPositionOf(readFileSync(b, 'utf8')) ||
      basename(a).localeCompare(basename(b)),
  );
  const sortAlpha = ALPHA_SORTED_DIR_NAMES.has(basename(dir));
  subdirs.sort((a, b) => {
    const ma = categoryMeta(join(dir, a));
    const mb = categoryMeta(join(dir, b));
    if (sortAlpha) return ma.label.localeCompare(mb.label, 'en', { ignorePunctuation: true });
    return ma.position - mb.position || a.localeCompare(b);
  });
  const children = [];
  if (indexPage) children.push({ type: 'page', abs: indexPage });
  for (const p of pages) children.push({ type: 'page', abs: p });
  for (const name of subdirs) {
    const abs = join(dir, name);
    const nested = walkDir(abs, docsRoot);
    const node = {
      type: 'category',
      abs,
      name,
      label: categoryMeta(abs).label,
      description: categoryMeta(abs).description,
      children: nested,
    };
    if (!subtreeHasPages(node)) continue;
    children.push(node);
  }
  return children;
}

export function walkDocsNav(docsRoot) {
  const items = [];
  for (const ent of listDirEntries(docsRoot)) {
    if (ent.name.startsWith('_')) continue;
    const abs = join(docsRoot, ent.name);
    if (ent.isDirectory()) {
      const meta = categoryMeta(abs);
      const node = {
        type: 'category',
        abs,
        name: ent.name,
        label: meta.label,
        description: meta.description,
        position: meta.position,
        children: walkDir(abs, docsRoot),
      };
      if (!subtreeHasPages(node)) continue;
      items.push(node);
      continue;
    }
    if (!isPublishablePageName(ent.name)) continue;
    items.push({
      type: 'page',
      abs,
      name: ent.name,
      position: sidebarPositionOf(readFileSync(abs, 'utf8')),
    });
  }
  items.sort((a, b) => a.position - b.position || a.name.localeCompare(b.name));
  return items;
}

function collectPages(node, docsRoot, env, out) {
  if (node.type === 'page') {
    out.push(pageRecord(node.abs, docsRoot, env));
    return;
  }
  for (const child of node.children ?? []) collectPages(child, docsRoot, env, out);
}

/**
 * Sections for llms.txt: one H2 per top-level nav item. Nested tool categories
 * become H3s. Generated-index landings are headings only (no page of their own).
 */
export function buildLlmsSections(docsRoot, env = process.env) {
  const nav = walkDocsNav(docsRoot);
  const sections = [];
  for (const item of nav) {
    if (item.type === 'page') {
      const page = pageRecord(item.abs, docsRoot, env);
      sections.push({ heading: page.title, level: 2, description: '', pages: [page] });
      continue;
    }
    const nested = (item.children ?? []).filter((c) => c.type === 'category' && subtreeHasPages(c));
    const direct = (item.children ?? []).filter((c) => c.type === 'page');
    if (nested.length) {
      if (direct.length) {
        const pages = [];
        for (const d of direct) collectPages(d, docsRoot, env, pages);
        sections.push({
          heading: item.label,
          level: 2,
          description: item.description,
          pages,
        });
      } else {
        sections.push({
          heading: item.label,
          level: 2,
          description: item.description,
          pages: [],
        });
      }
      for (const n of nested) {
        const pages = [];
        collectPages(n, docsRoot, env, pages);
        sections.push({
          heading: n.label,
          level: 3,
          description: n.description,
          pages,
        });
      }
      continue;
    }
    const pages = [];
    collectPages(item, docsRoot, env, pages);
    sections.push({
      heading: item.label,
      level: 2,
      description: item.description,
      pages,
    });
  }
  return sections;
}

export function flattenPages(sections) {
  const seen = new Set();
  const pages = [];
  for (const section of sections) {
    for (const page of section.pages) {
      if (seen.has(page.docPath)) continue;
      seen.add(page.docPath);
      pages.push(page);
    }
  }
  return pages;
}

const FAMILY_ORDER = [
  'overview',
  'configuration',
  'web-tools',
  'desktop-tools-sheets',
  'desktop-tools-data',
  'desktop-tools-session',
  'developers',
];

/** Families in canonical order, extras (unknown top-level folders) last. */
export function groupPagesByFamily(pages) {
  const order = [];
  const byId = new Map();
  for (const page of pages) {
    const id = page.familyId;
    if (!byId.has(id)) {
      byId.set(id, []);
      order.push(id);
    }
    byId.get(id).push(page);
  }
  const known = FAMILY_ORDER.filter((id) => byId.has(id));
  const extra = order.filter((id) => !FAMILY_ORDER.includes(id));
  return [...known, ...extra].map((id) => {
    const familyPages = byId.get(id);
    return {
      id,
      title: familyTitle(id, familyPages),
      pages: familyPages,
    };
  });
}

/** Shared family id when every page in a section belongs to one family. */
export function sectionFamilyId(section) {
  if (!section.pages.length) return null;
  const ids = new Set(section.pages.map((p) => p.familyId));
  return ids.size === 1 ? [...ids][0] : null;
}
